// Reporting window: yesterday 00:00 -> today 00:00, America/Chicago
const nowCT = DateTime.now().setZone('America/Chicago');
const start = nowCT.minus({ days: 1 }).startOf('day');
const end = nowCT.startOf('day');
return [{
  json: {
    window_start_iso: start.toUTC().toISO(),
    window_end_iso: end.toUTC().toISO(),
    window_start_ms: start.toMillis(),
    window_end_ms: end.toMillis(),
    report_date: start.toFormat('yyyy-LL-dd'),
    report_date_label: start.toFormat('cccc, LLLL d, yyyy'),
  }
}];

// Filter execution list to the reporting window; emit one item per execution
const win = $('Set Reporting Window').first().json;
const resp = $input.first().json || {};
const list = Array.isArray(resp.data) ? resp.data : [];
const inWindow = list.filter(e => {
  const t = new Date(e.startedAt).getTime();
  return t >= win.window_start_ms && t < win.window_end_ms;
});
if (inWindow.length === 0) {
  return [{ json: { no_executions: true } }];
}
return inWindow.map(e => ({
  json: {
    execution_id: String(e.id),
    startedAt: e.startedAt,
    status: e.status || (e.finished ? 'success' : 'unknown'),
    mode: e.mode || '',
  }
}));

// Classify every execution of the MQL Classification workflow and extract:
// outcome, thread/visitor identity, chat preview, source AI analysis, and
// the full field set for the data table (transcript, messages, errors, etc).
const items = $input.all();
const rows = [];
let noExec = false;

const getOut = (runData, name) => {
  try { return runData[name]?.[0]?.data?.main?.[0]?.[0]?.json || null; }
  catch (e) { return null; }
};
const stripHtml = (t) => String(t || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const cut = (t, n) => { const s = String(t ?? ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };

for (const item of items) {
  const exec = item.json || {};
  if (exec.no_executions) { noExec = true; continue; }
  if (exec.fetch_failed || (!exec.id && !exec.data)) {
    rows.push({ execution_id: String(exec.execution_id || 'unknown'), startedAt: exec.startedAt || '',
      status: 'fetch_failed', outcome: 'unknown', reason: 'Could not fetch execution detail from n8n API',
      threadId: '', contactId: '', mql_status: '', conversation_name: '', chat_preview: '',
      ai: {}, extra: {}, properties_written: null });
    continue;
  }

  const runData = exec.data?.resultData?.runData || {};
  const lastNode = exec.data?.resultData?.lastNodeExecuted || '';
  const errObj = exec.data?.resultData?.error || null;
  const ran = Object.keys(runData);

  const webhookOut = getOut(runData, 'HubSpot Closed Conversation Webhook');
  const normalizeOut = getOut(runData, 'Normalize Conversation + Transcript');
  const prepOut = getOut(runData, 'Prepare HubSpot Contact Fields');
  const msgsOut = getOut(runData, 'Get Thread Messages');
  const aiRaw = getOut(runData, 'Analyze + Draft Email');

  const threadId = String(normalizeOut?.threadId || webhookOut?.body?.hs_thread_id || '');
  const contactId = String(normalizeOut?.contactId || prepOut?.contactId || webhookOut?.body?.hs_object_id || '');

  // --- Source AI analysis ---
  let ai = {};
  let aiObj = aiRaw?.output ?? aiRaw;
  if (typeof aiObj === 'string') { try { aiObj = JSON.parse(aiObj.replace(/^```json\s*/i,'').replace(/```$/,'')); } catch (e) { aiObj = {}; } }
  if (aiObj && typeof aiObj === 'object') {
    ai = {
      summary: String(aiObj.summary || ''),
      intent_category: String(aiObj.intent_category || ''),
      lead_temperature: String(aiObj.lead_temperature || ''),
      confidence: aiObj.confidence !== undefined && aiObj.confidence !== '' ? String(aiObj.confidence) : '',
      hiring_count: String(aiObj.hiring_count || ''),
      lifecyclestage: String(aiObj.lifecyclestage || ''),
      ai_mql_response: String(aiObj.ai_mql_response_1 || ''),
      follow_up_email: String(aiObj.follow_up_email_body || aiObj.ai_mql_response_1 || ''),
    };
  }

  // --- Conversation identity + messages ---
  const msgs = Array.isArray(msgsOut?.results) ? msgsOut.results : [];
  const incoming = msgs.filter(m => m.type === 'MESSAGE' && m.direction === 'INCOMING');
  const outgoing = msgs.filter(m => m.type === 'MESSAGE' && m.direction === 'OUTGOING');
  let visitorLabel = '';
  for (const m of incoming) {
    const s = (m.senders || [])[0] || {};
    if (s.name) { visitorLabel = s.name; break; }
  }
  if (!visitorLabel) {
    const firstIn = stripHtml(incoming[0]?.text);
    const emailMatch = firstIn.match(/[\w.+-]+@[\w-]+\.[\w.]+/);
    if (emailMatch) visitorLabel = emailMatch[0];
    else if (firstIn) visitorLabel = firstIn.slice(0, 40);
  }
  const visitorMessages = cut(incoming.map(m => stripHtml(m.text)).filter(Boolean).join(' | '), 4000);
  const chat_preview = cut(incoming.slice(0, 3).map(m => stripHtml(m.text)).filter(Boolean).join(' | '), 240)
    || cut(stripHtml(outgoing[0]?.text), 160);
  const conversation_name =
    (prepOut && (prepOut.firstname || prepOut.lastname)) ? `${prepOut.firstname || ''} ${prepOut.lastname || ''}`.trim()
    : visitorLabel ? visitorLabel
    : threadId ? `Anonymous visitor (thread ${threadId})` : 'Unknown conversation';

  // --- Full transcript (before we strip it from properties_written) ---
  const fullTranscript = cut(
    prepOut?.chatbot_transcript || normalizeOut?.chatbot_transcript || normalizeOut?.transcript ||
    msgs.filter(m => m.type === 'MESSAGE').map(m => `${m.direction === 'INCOMING' ? 'Visitor' : 'Maia'}: ${stripHtml(m.text)}`).join('\n'),
    30000);

  // --- Outcome classification ---
  let outcome = 'incomplete';
  let reason = `Stopped at ${lastNode || 'unknown node'}`;
  const errMsg = String(errObj?.message || '');
  if (errObj && errMsg.includes("hasn't been executed") && errMsg.includes('Find Contact')) {
    outcome = 'dropped';
    reason = 'Anonymous visitor — conversation closed with no contact (Find Contact skipped, Normalize failed on missing reference)';
  } else if (errObj) {
    outcome = 'error';
    const nodeName = errObj.node?.name || lastNode || 'unknown node';
    reason = `Error at "${nodeName}": ${errMsg.slice(0, 300) || 'unknown error'}`;
  } else if (ran.includes('Create or update a contact') || ran.includes('Create or update a contact1')) {
    outcome = 'contact_updated';
    reason = 'Contact created/updated with chatbot analysis';
  } else if (!ran.includes('Find Contact') && !ran.includes('Get Conversation Thread')) {
    outcome = 'dropped';
    reason = 'No contact on conversation — visitor never shared an email (filtered at If1)';
  } else if (ran.includes('Normalize Conversation + Transcript') && !ran.includes('Analyze + Draft Email')) {
    outcome = 'dropped';
    reason = 'Normalize ended run — no contact id resolved or empty transcript';
  }

  let props = null;
  if (prepOut && typeof prepOut === 'object') {
    props = { ...prepOut };
    if (props.chatbot_transcript) {
      props.chatbot_transcript_length = String(props.chatbot_transcript).length;
      delete props.chatbot_transcript;
    }
  }

  rows.push({
    execution_id: String(exec.id || ''),
    startedAt: exec.startedAt || '',
    status: exec.status || '',
    mode: exec.mode || '',
    outcome, reason, threadId, contactId, conversation_name, chat_preview,
    mql_status: props?.chatbot_mql_status || '',
    ai,
    extra: {
      visitor_messages: visitorMessages,
      full_transcript: fullTranscript,
      last_node: lastNode,
      error_node: errObj ? (errObj.node?.name || lastNode || '') : '',
      error_message: errObj ? cut(errMsg, 500) : '',
      phone: prepOut?.phone || '',
      domain: prepOut?.domain || '',
      website: prepOut?.website || '',
      firstname: prepOut?.firstname || '',
      lastname: prepOut?.lastname || '',
    },
    properties_written: props,
  });
}

rows.sort((a, b) => String(a.startedAt).localeCompare(String(b.startedAt)));

const stats = {
  conversations_in: rows.length,
  contacts_updated: rows.filter(r => r.outcome === 'contact_updated').length,
  dropped: rows.filter(r => r.outcome === 'dropped').length,
  errors: rows.filter(r => r.outcome === 'error').length,
  incomplete: rows.filter(r => r.outcome === 'incomplete' || r.outcome === 'unknown').length,
  mql: rows.filter(r => String(r.mql_status).toLowerCase() === 'mql').length,
};
stats.non_mql = stats.contacts_updated - stats.mql;
stats.mql_rate = stats.contacts_updated > 0 ? Math.round((stats.mql / stats.contacts_updated) * 100) : 0;

const dropReasons = {};
for (const r of rows) {
  if (r.outcome === 'dropped' || r.outcome === 'error') {
    dropReasons[r.reason] = (dropReasons[r.reason] || 0) + 1;
  }
}

return [{ json: { exec_rows: rows, exec_stats: stats, drop_reasons: dropReasons, no_data: noExec && rows.length === 0 } }];

// Merge n8n execution outcomes with live HubSpot contact records + prep AI input
const parsed = $('Parse Execution Outcomes').first().json;
const win = $('Set Reporting Window').first().json;
const searchResp = $input.first().json || {};
const contacts = Array.isArray(searchResp.results) ? searchResp.results : [];

const byId = {};
for (const c of contacts) byId[String(c.id)] = c.properties || {};

const CHATBOT_PROPS = [
  'chatbot_mql_status','chatbot_eor_intent','chatbot_countries','chatbot_timeline',
  'chatbot_wses','chatbot_buyer_need','chatbot_pain_points','chatbot_questions_asked',
  'chatbot_recommended_next_step','chatbot_disqualification_reason','chatbot_session_id',
  'chatbot_last_session_date','ai_chatbot_processed'
];

const masterRows = [];
for (const r of parsed.exec_rows || []) {
  const hs = byId[r.contactId] || {};
  const p = r.properties_written || {};
  const val = (k) => (p[k] !== undefined && p[k] !== '' ? p[k] : (hs[k] || ''));
  masterRows.push({
    startedAt: r.startedAt,
    execution_id: r.execution_id,
    threadId: r.threadId,
    contactId: r.contactId,
    conversation_name: r.conversation_name || '',
    chat_preview: r.chat_preview || '',
    status: r.status || '',
    mode: r.mode || '',
    outcome: r.outcome,
    reason: r.reason,
    email: p.email || hs.email || '',
    name: [p.firstname || hs.firstname || '', p.lastname || hs.lastname || ''].join(' ').trim(),
    company: p.company || hs.company || '',
    jobtitle: p.jobtitle || hs.jobtitle || '',
    lifecyclestage: hs.lifecyclestage || r.ai?.lifecyclestage || '',
    lead_status: hs.hs_lead_status || '',
    extra: r.extra || {},
    ai: r.ai || {},
    props: Object.fromEntries(CHATBOT_PROPS.map(k => [k, val(k)])),
  });
}

const seenContacts = new Set(masterRows.map(r => r.contactId).filter(Boolean));
const orphanContacts = contacts.filter(c => !seenContacts.has(String(c.id))).map(c => ({
  contactId: String(c.id),
  email: c.properties?.email || '',
  name: [c.properties?.firstname || '', c.properties?.lastname || ''].join(' ').trim(),
  mql_status: c.properties?.chatbot_mql_status || '',
}));

const mqlRows = masterRows
  .filter(r => r.outcome === 'contact_updated')
  .map(r => ({
    email: r.email || r.contactId,
    company: r.company,
    mql_status: r.props.chatbot_mql_status || 'Unknown',
    why: String(r.props.chatbot_mql_status).toLowerCase() === 'mql'
      ? (r.props.chatbot_buyer_need || 'Buyer need identified')
      : (r.props.chatbot_disqualification_reason || r.props.chatbot_buyer_need || 'No qualifying signals'),
    countries: r.props.chatbot_countries || '',
    timeline: r.props.chatbot_timeline || '',
    intent: r.props.chatbot_eor_intent || '',
  }));

const countries = {};
for (const r of masterRows) {
  for (const c of String(r.props.chatbot_countries || '').split(';').map(s => s.trim()).filter(Boolean)) {
    countries[c] = (countries[c] || 0) + 1;
  }
}

// Compact per-conversation payload for the report AI (structured output)
const aiConversations = masterRows.map(r => ({
  thread_id: r.threadId,
  who: r.name || r.email || r.conversation_name,
  company: r.company,
  outcome: r.outcome,
  reason: r.outcome === 'contact_updated' ? '' : r.reason,
  mql_status: r.props.chatbot_mql_status || '',
  source_summary: r.ai.summary || '',
  buyer_need: String(r.props.chatbot_buyer_need || '').slice(0, 300),
  pain_points: String(r.props.chatbot_pain_points || '').slice(0, 200),
  countries: r.props.chatbot_countries || '',
  timeline: r.props.chatbot_timeline || '',
  intent_category: r.ai.intent_category || '',
  lead_temperature: r.ai.lead_temperature || '',
  chat_preview: r.chat_preview || '',
  recommended_next_step: String(r.props.chatbot_recommended_next_step || '').slice(0, 200),
}));

const stats = {
  ...parsed.exec_stats,
  hubspot_contacts_touched: contacts.length,
  orphan_contacts: orphanContacts.length,
};

return [{
  json: {
    report_date: win.report_date,
    report_date_label: win.report_date_label,
    stats,
    drop_reasons: parsed.drop_reasons || {},
    master_rows: masterRows,
    mql_rows: mqlRows,
    orphan_contacts: orphanContacts,
    countries,
    ai_conversations: aiConversations,
    no_data: parsed.no_data === true,
  }
}];

// Render the Atlas-branded daily report email (v2 — AI structured output aware)
const d = $('Build Master Table + Stats').first().json;
const aiIn = $input.first().json || {};
let ai = aiIn.output;
if (typeof ai === 'string') { try { ai = JSON.parse(ai); } catch (e) { ai = null; } }
if (!ai || typeof ai !== 'object') ai = {};
const narrative = String(ai.narrative || aiIn.text || aiIn.response || '').trim();
const highlights = Array.isArray(ai.highlights) ? ai.highlights.filter(Boolean) : [];
let convRows = Array.isArray(ai.conversation_rows) ? ai.conversation_rows : [];

// Deterministic fallback if the AI table is missing
if (!convRows.length) {
  convRows = (d.master_rows || []).map(r => ({
    thread_id: r.threadId,
    who: r.name || r.email || r.conversation_name,
    company: r.company,
    mql_status: r.props?.chatbot_mql_status || (r.outcome === 'contact_updated' ? 'Unknown' : '—'),
    chat_summary: r.ai?.summary || r.chat_preview || '',
    key_signals: [r.props?.chatbot_countries, r.props?.chatbot_timeline, r.ai?.lead_temperature].filter(Boolean).join(' · '),
    recommended_action: r.props?.chatbot_recommended_next_step || '',
  }));
}

const esc = (v) => String(v ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const NAVY = '#160629', BLUE = '#0559FA', GREY = '#f4f5f9';
const s = d.stats || {};
const short = (v, n = 160) => { const t = String(v ?? ''); return t.length > n ? t.slice(0, n - 1) + '…' : t; };

const kpi = (label, value, color) => `
  <td style="padding:14px 18px;background:${GREY};border-radius:8px;text-align:center;">
    <div style="font-size:26px;font-weight:700;color:${color || NAVY};">${esc(value)}</div>
    <div style="font-size:11px;letter-spacing:.5px;text-transform:uppercase;color:#666;">${esc(label)}</div>
  </td><td style="width:8px;"></td>`;

const th = (h) => `<th style="padding:6px 10px;background:${GREY};text-align:left;font-size:11px;">${esc(h)}</th>`;
const td = (c, extra='') => `<td style="padding:6px 10px;border-bottom:1px solid #eee;font-size:12px;vertical-align:top;${extra}">${c}</td>`;

const badge = (status) => {
  const t = String(status || '').toLowerCase();
  const good = t === 'mql';
  const na = t === '—' || t === '';
  const bg = na ? '#eef0f4' : good ? '#e6f9ed' : '#feecec';
  const fg = na ? '#667' : good ? '#0a7a3d' : '#b42318';
  return `<span style="background:${bg};color:${fg};padding:2px 10px;border-radius:10px;font-weight:600;font-size:11px;">${esc(status || '—')}</span>`;
};

// Conversation summaries (AI-generated)
const convTable = convRows.map(r => `<tr>
  ${td(esc(r.who || '') + (r.company ? `<br/><span style="color:#888;">${esc(r.company)}</span>` : ''))}
  ${td(esc(r.thread_id || ''))}
  ${td(badge(r.mql_status), 'text-align:center;')}
  ${td(esc(short(r.chat_summary, 400)))}
  ${td(esc(short(r.key_signals, 160)))}
  ${td(esc(short(r.recommended_action, 200)))}
</tr>`).join('') || `<tr><td colspan="6" style="padding:8px;color:#888;">No conversations in this window.</td></tr>`;

// Drops — now with conversation identity + preview
const dropDetail = (d.master_rows || []).filter(r => r.outcome === 'dropped' || r.outcome === 'error');
const dropRows = dropDetail.map(r => `<tr>
  ${td(esc(r.conversation_name || 'Unknown'))}
  ${td(esc(r.threadId))}
  ${td(esc(short(r.reason, 180)))}
  ${td(esc(short(r.chat_preview, 220)))}
</tr>`).join('') || `<tr><td colspan="4" style="padding:8px;color:#888;">No drops or errors — every conversation reached the contact update.</td></tr>`;

const mqlRows = (d.mql_rows || []).map(r => `<tr>
  ${td(esc(r.email))}${td(esc(r.company))}
  ${td(badge(r.mql_status), 'text-align:center;')}
  ${td(esc(short(r.why, 300)))}${td(esc(r.countries))}${td(esc(r.timeline))}
</tr>`).join('') || '<tr><td colspan="6" style="padding:8px;color:#888;">No contacts were updated in this window.</td></tr>';

const P = ['chatbot_mql_status','chatbot_eor_intent','chatbot_countries','chatbot_timeline','chatbot_wses','chatbot_buyer_need','chatbot_pain_points','chatbot_questions_asked','chatbot_recommended_next_step','chatbot_disqualification_reason','chatbot_session_id','chatbot_last_session_date','ai_chatbot_processed'];
const AIF = [['summary','AI summary'],['intent_category','intent category'],['lead_temperature','lead temp'],['confidence','confidence'],['hiring_count','hiring count']];
const headCells = ['Time (CT)','Exec ID','Thread','Conversation','Contact','Email / Name','Company','Outcome','Reason', ...AIF.map(x=>x[1]), ...P.map(k => k.replace('chatbot_','').replace(/_/g,' '))]
  .map(h => `<th style="padding:6px 8px;background:${NAVY};color:#fff;font-size:10px;text-transform:uppercase;letter-spacing:.4px;text-align:left;white-space:nowrap;">${esc(h)}</th>`).join('');

const masterRows = (d.master_rows || []).map(r => {
  const t = r.startedAt ? new Date(r.startedAt).toLocaleTimeString('en-US',{timeZone:'America/Chicago',hour:'2-digit',minute:'2-digit'}) : '';
  const cells = [t, r.execution_id, r.threadId, r.conversation_name, r.contactId,
    `${esc(r.email)}${r.name ? '<br/><span style="color:#888;">'+esc(r.name)+'</span>' : ''}`,
    r.company, r.outcome, short(r.reason, 120),
    ...AIF.map(x => short(r.ai?.[x[0]])),
    ...P.map(k => short(r.props?.[k]))];
  return `<tr>${cells.map((c, i) => `<td style="padding:5px 8px;border-bottom:1px solid #eee;font-size:11px;vertical-align:top;">${i===5?c:esc(c)}</td>`).join('')}</tr>`;
}).join('') || '<tr><td colspan="27" style="padding:8px;color:#888;">No executions in this window.</td></tr>';

const countryList = Object.entries(d.countries || {}).sort((a,b)=>b[1]-a[1]).slice(0,8)
  .map(([c,n]) => `${esc(c)} (${n})`).join(' · ') || '—';

const orphanNote = (d.orphan_contacts || []).length
  ? `<p style="font-size:12px;color:#b45309;background:#fef3c7;padding:8px 12px;border-radius:6px;">⚠️ ${d.orphan_contacts.length} contact(s) updated in HubSpot yesterday with chatbot properties but no matching n8n execution: ${d.orphan_contacts.map(o=>esc(o.email||o.contactId)).join(', ')}</p>` : '';

const highlightsHtml = highlights.length
  ? `<ul style="margin:8px 0 0;padding-left:18px;font-size:13px;line-height:1.6;">${highlights.map(h=>`<li>${esc(h)}</li>`).join('')}</ul>` : '';

const html = `
<div style="font-family:Segoe UI,Helvetica,Arial,sans-serif;max-width:1100px;margin:0 auto;color:${NAVY};">
  <div style="background:${NAVY};padding:22px 26px;border-radius:10px 10px 0 0;">
    <div style="color:#fff;font-size:20px;font-weight:700;">Maia Chatbot — Daily Report</div>
    <div style="color:#9aa4c7;font-size:13px;margin-top:4px;">${esc(d.report_date_label)} · Marketing Chatbot | MQL Classification · Atlas HXM GTM AI</div>
  </div>
  <div style="padding:22px 26px;background:#fff;border:1px solid #e8e8f0;border-top:none;border-radius:0 0 10px 10px;">
    ${narrative ? `<div style="background:${GREY};border-left:4px solid ${BLUE};padding:12px 16px;border-radius:6px;font-size:14px;line-height:1.55;margin-bottom:18px;">${esc(narrative)}${highlightsHtml}</div>` : ''}
    <table style="border-collapse:separate;width:100%;margin-bottom:20px;"><tr>
      ${kpi('Conversations In', s.conversations_in ?? 0)}
      ${kpi('Contacts Updated', s.contacts_updated ?? 0, BLUE)}
      ${kpi('MQLs', s.mql ?? 0, '#0a7a3d')}
      ${kpi('MQL Rate', (s.mql_rate ?? 0) + '%')}
      ${kpi('Dropped', s.dropped ?? 0, '#b45309')}
      ${kpi('Errors', s.errors ?? 0, '#b42318')}
    </tr></table>
    <p style="font-size:12px;color:#666;margin:0 0 18px;">Top countries: ${countryList}</p>
    ${orphanNote}

    <h3 style="font-size:14px;margin:18px 0 8px;color:${NAVY};">Conversation summaries</h3>
    <table style="border-collapse:collapse;width:100%;font-size:12px;">
      <tr>${['Who','Thread','Status','Chat summary','Key signals','Recommended action'].map(th).join('')}</tr>
      ${convTable}
    </table>

    <h3 style="font-size:14px;margin:22px 0 8px;color:${NAVY};">Conversations that didn't create/update a contact</h3>
    <table style="border-collapse:collapse;width:100%;font-size:12px;">
      <tr>${['Conversation','Thread','Why no contact','What they said'].map(th).join('')}</tr>
      ${dropRows}
    </table>

    <h3 style="font-size:14px;margin:22px 0 8px;color:${NAVY};">MQL decisions — why each contact was (or wasn't) an MQL</h3>
    <table style="border-collapse:collapse;width:100%;font-size:12px;">
      <tr>${['Email','Company','Status','Why','Countries','Timeline'].map(th).join('')}</tr>
      ${mqlRows}
    </table>

    <h3 style="font-size:14px;margin:22px 0 8px;color:${NAVY};">Master table — every execution, thread, contact & all HubSpot properties written</h3>
    <div style="overflow-x:auto;">
      <table style="border-collapse:collapse;min-width:1200px;">
        <tr>${headCells}</tr>
        ${masterRows}
      </table>
    </div>
    <p style="font-size:11px;color:#999;margin-top:16px;">Transcripts excluded (length shown). Rows are also appended to the “Maia Report Master” data table in n8n. Window: ${esc(d.report_date)} 00:00–24:00 CT.</p>
  </div>
</div>`;

const mqlCount = s.mql ?? 0;
const subject = `Maia Daily Report — ${d.report_date}: ${s.conversations_in ?? 0} conversations, ${s.contacts_updated ?? 0} contacts updated, ${mqlCount} MQL${mqlCount === 1 ? '' : 's'}`;

return [{ json: { subject, html } }];

