// One flat item per conversation — keys match the "chatbot CRM n8n outputs" data table exactly
const d = $input.first().json;
const fmt = (iso, tz) => {
  if (!iso) return '';
  const dt = new Date(iso);
  const p = new Intl.DateTimeFormat('en-US', { timeZone: tz, year: 'numeric', month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false }).formatToParts(dt);
  const g = (t) => p.find(x => x.type === t)?.value || '';
  return `${g('month')}/${g('day')}/${g('year')} ${g('hour')}:${g('minute')}`;
};
const out = [];
let i = 0;
for (const r of d.master_rows || []) {
  i += 1;
  const p = r.props || {}, a = r.ai || {}, x = r.extra || {};
  out.push({ json: {
    '#': String(i),
    'Execution ID': r.execution_id,
    'Started (UTC)': fmt(r.startedAt, 'UTC'),
    'Started (Central)': fmt(r.startedAt, 'America/Chicago'),
    'Status': r.status || '',
    'Failure Reason': r.outcome === 'contact_updated' ? '' : r.reason,
    'Mode': r.mode || '',
    'Thread ID': r.threadId,
    'Contact ID': r.contactId,
    'First Name': x.firstname || '',
    'Last Name': x.lastname || '',
    'Email': r.email || '',
    'Phone': x.phone || '',
    'Job Title': r.jobtitle || '',
    'Company': r.company || '',
    'Domain': x.domain || '',
    'Website': x.website || '',
    'MQL Status': p.chatbot_mql_status || '',
    'Confidence': a.confidence || '',
    'Lifecycle Stage': r.lifecyclestage || '',
    'Lead Status': r.lead_status || '',
    'Lead Temp': a.lead_temperature || '',
    'Intent Category': a.intent_category || '',
    'EOR Intent': p.chatbot_eor_intent || '',
    'Hiring Count': a.hiring_count || '',
    'Hiring Timeline': p.chatbot_timeline || '',
    'Countries': p.chatbot_countries || '',
    'Workforce Setup': p.chatbot_wses || '',
    'Buyer Need': p.chatbot_buyer_need || '',
    'Pain Points': p.chatbot_pain_points || '',
    'Questions Asked': p.chatbot_questions_asked || '',
    'Recommended Next Step': p.chatbot_recommended_next_step || '',
    'Disqualification Reason': p.chatbot_disqualification_reason || '',
    'Chat Summary': a.summary || '',
    'AI MQL Response': a.ai_mql_response || '',
    'Follow-up Email': a.follow_up_email || '',
    'Visitor Messages': x.visitor_messages || '',
    'Full Transcript': x.full_transcript || '',
    'Last Node Executed': x.last_node || '',
    'Error Node': x.error_node || '',
    'Error Message': x.error_message || '',
  }});
}
return out;

// One row per day — matches the "Maia Report Daily Summary" data table
const d = $input.first().json;
const s = d.stats || {};
const topCountries = Object.entries(d.countries || {}).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([c,n])=>`${c} (${n})`).join('; ');
const topDrop = Object.entries(d.drop_reasons || {}).sort((a,b)=>b[1]-a[1]).map(([r,n])=>`${r} ×${n}`).join(' | ');
return [{ json: {
  report_date: d.report_date,
  conversations_in: s.conversations_in ?? 0,
  contacts_updated: s.contacts_updated ?? 0,
  mql: s.mql ?? 0,
  non_mql: s.non_mql ?? 0,
  mql_rate: s.mql_rate ?? 0,
  dropped: s.dropped ?? 0,
  errors: s.errors ?? 0,
  top_countries: topCountries,
  drop_reasons: topDrop,
}}];
